import{_ as s,o as n,c as e,a4 as p}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"虚拟内存与地址翻译","description":"","frontmatter":{},"headers":[],"relativePath":"os/memory/virtual-memory.md","filePath":"os/memory/virtual-memory.md","lastUpdated":1788475713000}'),t={name:"os/memory/virtual-memory.md"};function l(i,a,o,c,r,d){return n(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="虚拟内存与地址翻译" tabindex="-1">虚拟内存与地址翻译 <a class="header-anchor" href="#虚拟内存与地址翻译" aria-label="Permalink to &quot;虚拟内存与地址翻译&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>你不是直接写 RAM——你写的地址是进程的&quot;虚拟地址&quot;。从 <code>mov rax, [0x7ffe]</code> 到 DRAM chip 收到字节，要经过 <strong>MMU + 页表 + TLB + cache + memory controller + DRAM row activate + column</strong> 这几层抽象。每跨一层都加一个常数。这一章把翻译链拆开，让你看到 <code>mov</code> 这一句汇编后面到底经历了什么。</p><h2 id="虚拟地址到底-虚拟-什么" tabindex="-1">虚拟地址到底&quot;虚拟&quot;什么 <a class="header-anchor" href="#虚拟地址到底-虚拟-什么" aria-label="Permalink to &quot;虚拟地址到底&quot;虚拟&quot;什么&quot;">​</a></h2><p>进程地址空间是 OS 给的&quot;幻觉&quot;：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>进程 A：</span></span>
<span class="line"><span>  0x0000-0x7fff 代码 + 数据 + 堆</span></span>
<span class="line"><span>  0x7ffe-0x8000 栈</span></span>
<span class="line"><span></span></span>
<span class="line"><span>进程 B：</span></span>
<span class="line"><span>  0x0000-0x7fff 代码 + 数据 + 堆</span></span>
<span class="line"><span>  0x7ffe-0x8000 栈</span></span></code></pre></div><p>两个进程都用 0x400000，独立，互不见对方的内存。<strong>这是虚拟内存唯一目的：进程隔离 + 让程序以为自己独占机器</strong>。</p><p>实现上靠 Page Table：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>进程虚拟地址 0x7fec_1234</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>    [页表映射]</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>   物理页帧号 + 页内偏移</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>       DRAM 地址</span></span></code></pre></div><p>每条 <code>mov</code> 都要 MMU 走一遍页表翻译——如果不缓存就一次翻译要 5 次内存读，IO 拖到几百 ns，CPU 跑不动。这就是为什么 TLB 是 MMU 必备的缓存。</p><h2 id="地址翻译链路" tabindex="-1">地址翻译链路 <a class="header-anchor" href="#地址翻译链路" aria-label="Permalink to &quot;地址翻译链路&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>虚拟地址 (VA)</span></span>
<span class="line"><span>  = VPN(高 bit)  + PageOffset(低 12 bit, 4 KB page)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>[ L1 TLB → L2 TLB → Page table walk ]</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>物理页帧号 (PFN)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>PA = PFN · PAGE_SIZE + PageOffset</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>[ L1 cache → L2/L3 → DRAM ]</span></span></code></pre></div><p>每一步都&quot;可能 miss&quot;。TLB miss 称&quot;地址翻译 stall&quot;；cache miss 称&quot;data stall&quot;。一次访存 if 都 miss 可能 100-200 ns. CPU 看到的 <code>mov rax, [x]</code> 这种简单操作在最坏情形可消耗 200 倍 cycle.</p><h2 id="三级-四级页表的真正原因" tabindex="-1">三级/四级页表的真正原因 <a class="header-anchor" href="#三级-四级页表的真正原因" aria-label="Permalink to &quot;三级/四级页表的真正原因&quot;">​</a></h2><p>页表本身大；按 ridged 32-bit 系统：</p><ul><li>4 KB page × 32-bit 虚拟地址 = 2^20 个 page = 1 M entry × 8B = 8 MB / proc</li></ul><p><strong>进程 4 GB 虚拟空间页表全表 = 8 MB. 一个 64 GB 内存机器最多跑 8192 个 4GB 进程就炸</strong>——还是没算 OS 自己内存. 这就是&quot;flat page table 不行&quot;.</p><p>多级页表的核心思想: <strong>未使用的虚拟地址范围不需在内存里建中间节点</strong>.</p><p>64-bit x86 long mode 使用 4 级页表 (CR3 + 4 · 9-bit index，每级 512 项):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>9 bit  9 bit  9 bit  9 bit  12 bit</span></span>
<span class="line"><span>PML4   PDPT   PD     PT     Page offset</span></span></code></pre></div><p>5-level paging (LA57) 加一级 + 9 bit = 支持 57 bit VA.</p><p>中间表项不存在就直接 &quot;page fault&quot;——不分配 page. 这让一个进程的页表绝大多数并未物化. <strong>这是多级页表的&quot;课&quot;：稀疏内容的物化使用&quot;懒&quot;的精神</strong>.</p><p>类比 DSA：B 树与多级页表的根同源 —— <strong>i级索引稀疏, leaf 真物理</strong>. 这就是分隔中大幅降低空间复杂度的同一思想。</p><h2 id="tlb-把-翻译本身-也加-cache" tabindex="-1">TLB: 把&quot;翻译本身&quot;也加 cache <a class="header-anchor" href="#tlb-把-翻译本身-也加-cache" aria-label="Permalink to &quot;TLB: 把&quot;翻译本身&quot;也加 cache&quot;">​</a></h2><p>CPU 内部 L1/L2 TLB 缓存最近几条 VA→PA 翻译：</p><ul><li>L1 DTLB: 64-128 entry, ~1 cycle 全命中</li><li>L2 STLB (shared TLB): 1K-4K entry, ~7 cycle</li><li>OS 上下文切换时 invalidate 整个 TLB（旧架构）</li></ul><p>5-level LA57 后, working set 翻译加深的概率大幅上升 —— <strong>TLB miss 已经不再是 small CPU 内部常数</strong>, 而是内存级 (几十 ns) 浪费. 现代 Intel CPU 把 TLB 全部 keep in L2/L3 一致, &quot;process-context id (PCID)&quot; 让切换时不 invalidate TLB —— 节省 1-3% 系统时间.</p><h2 id="虚拟内存的-5-个-ease-用" tabindex="-1">虚拟内存的 5 个 ease 用 <a class="header-anchor" href="#虚拟内存的-5-个-ease-用" aria-label="Permalink to &quot;虚拟内存的 5 个 ease 用&quot;">​</a></h2><ol><li><strong>进程隔离</strong>: 每个进程独立 VA.</li><li><strong>懒载入</strong>: <code>mmap</code> 后不实际加载, 真用时 page fault 触发 IO.</li><li><strong>COW (copy-on-write)</strong>: <code>fork()</code> 不复制整个父进程内存, 只把所有页标 readonly, 写时再复制.</li><li><strong>swap</strong>: 内存压力大时把不活跃页换到磁盘.</li><li><strong>mmap files</strong>: 把文件按页映射到虚拟空间, &quot;读文件&quot; = 读内存.</li></ol><p>每一个 ease 用都是&quot;懒 + cache&quot; 的同一抽象: 实际上不立即做事，等真触发了再做。</p><h2 id="性能上要关心的事" tabindex="-1">性能上要关心的事 <a class="header-anchor" href="#性能上要关心的事" aria-label="Permalink to &quot;性能上要关心的事&quot;">​</a></h2><h3 id="tlb-shootdown-的代价" tabindex="-1">TLB shootdown 的代价 <a class="header-anchor" href="#tlb-shootdown-的代价" aria-label="Permalink to &quot;TLB shootdown 的代价&quot;">​</a></h3><p>当某个进程页表项被修改（如 munmap、用户主动改保护位），所有可能持有这条 TLB 项的 CPU 都要 invalidate. 这是 IPI (inter-processor interrupt)，<strong>单机下微秒级</strong>, 在 100 核机器上 shootdown 可达 50+ μs.</p><p>解决方案：</p><ul><li>PCID: 减少跨进程切换全 invalidate;</li><li>Lazy shootdown: 延迟到该 CPU 再次访问;</li><li>大页 / huge page: 减少需要缓存的 TLB 项数量。</li></ul><h3 id="大页的对比" tabindex="-1">大页的对比 <a class="header-anchor" href="#大页的对比" aria-label="Permalink to &quot;大页的对比&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>4 KB page、1 GB 内存 = 2^18 个 page.</span></span>
<span class="line"><span>1 GB huge page、1 GB = 1 个 page.</span></span></code></pre></div><p>TLB 容量小但 huge page 占一项就 hardware 抑制了 1 GB. <strong>hotspot 应用开 huge page 通常 P99 抖动立刻降 30-50%</strong>。但需要注意 huge page 容易 fragment，不建议完全 global 启用。</p><h2 id="调试技巧" tabindex="-1">调试技巧 <a class="header-anchor" href="#调试技巧" aria-label="Permalink to &quot;调试技巧&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>检查别墅页表 (PID=1234)</span></span>
<span class="line"><span>cat /proc/1234/maps              # 用户态 VA 布局</span></span>
<span class="line"><span>pmap -x 1234                     # 进程内存布局</span></span>
<span class="line"><span>sudo cat /proc/1234/smaps        # 每段 VMA 详情</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>检查 page table walk 性能</span></span>
<span class="line"><span>perf stat -e page-faults,minor-faults,major-faults ./yourapp</span></span>
<span class="line"><span>perf stat -e dTLB-load-misses,iTLB-load-misses ./yourapp</span></span></code></pre></div><h2 id="这章带走的东西" tabindex="-1">这章带走的东西 <a class="header-anchor" href="#这章带走的东西" aria-label="Permalink to &quot;这章带走的东西&quot;">​</a></h2><ul><li>虚拟内存 = 进程隔离 + 懒加载 + COW + swap + mmap 五件套;</li><li>4 级页表 = 用稀疏内容让物化内存变小;</li><li>TLB miss 是常被忽略的性能杀手, huge page 是工程上 mitigations;</li><li>一次 <code>mov rax,[0x7ffe]</code> 最坏 200+ cycle, 因为翻译通路要全走一遍;</li><li><code>/proc/&lt;pid&gt;/{maps,smaps}</code> 是入口起点.</li></ul><p>下一节 → <a href="./tlb-hugepage">分页、TLB、Huge Page</a></p>`,44)])])}const g=s(t,[["render",l]]);export{u as __pageData,g as default};
